    AND p.moderation_status='BLOCKED'
    AND p.status=#{status}

mapper.select:
SELECT p.shop_id shopId,p.moderation_status moderationStatus,s.status shopStatus
FROM showcase_product p JOIN showcase_shop s ON s.id=p.shop_id
WHERE p.id=#{id} AND s.owner_username=#{username}
